import { SlashCommandBuilder, PermissionFlagsBits, ChatInputCommandInteraction, EmbedBuilder } from 'discord.js';
import ModerationCase from '../../../../models/ModerationCase.model';
import { EMOJIS } from '../../../shared/constants/emojis';

export default {
    data: new SlashCommandBuilder()
            .setName('ban')
                    .setDescription('Permanently bans a member from the server.')
                            .addUserOption(option => 
                                        option.setName('target').setDescription('The member to ban').setRequired(true))
                                                .addStringOption(option => 
                                                            option.setName('reason').setDescription('Reason for the ban').setRequired(false))
                                                                    .addIntegerOption(option => 
                                                                                option.setName('days').setDescription('Days of message history to delete (0-7)').setRequired(false).setMinValue(0).setMaxValue(7))
                                                                                        .setDefaultMemberPermissions(PermissionFlagsBits.BanMembers),

                                                                                            async execute(interaction: ChatInputCommandInteraction) {
                                                                                                    const guild = interaction.guild;
                                                                                                            if (!guild) return interaction.reply({ content: 'This command can only be used in a server.', ephemeral: true });

                                                                                                                    const target = interaction.options.getUser('target');
                                                                                                                            const reason = interaction.options.getString('reason') || 'No reason provided';
                                                                                                                                    const deleteDays = interaction.options.getInteger('days') as number || 0;

                                                                                                                                            if (!target) {
                                                                                                                                                        return interaction.reply({ 
                                                                                                                                                                        embeds: [new EmbedBuilder().setColor(0xef4444).setDescription(`${EMOJIS.MOD.CROSS} **Error:** User not found.`)], 
                                                                                                                                                                                        ephemeral: true 
                                                                                                                                                                                                    });
                                                                                                                                                                                                            }

                                                                                                                                                                                                                    if (target.id === interaction.user.id) {
                                                                                                                                                                                                                                return interaction.reply({ 
                                                                                                                                                                                                                                                embeds: [new EmbedBuilder().setColor(0xef4444).setDescription(`${EMOJIS.MOD.CROSS} **Action Failed:** You cannot ban yourself.`)], 
                                                                                                                                                                                                                                                                ephemeral: true 
                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                            await interaction.deferReply();

                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                                const targetMember = await guild.members.fetch(target.id).catch(() => null);
                                                                                                                                                                                                                                                                                                                            if (targetMember && targetMember.roles.highest.position >= guild.members.me!.roles.highest.position) {
                                                                                                                                                                                                                                                                                                                                            return interaction.editReply({ 
                                                                                                                                                                                                                                                                                                                                                                embeds: [new EmbedBuilder().setColor(0xef4444).setDescription(`${EMOJIS.MOD.CROSS} **Hierarchy Error:** I cannot ban this member.`)] 
                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                        await guild.members.ban(target.id, { 
                                                                                                                                                                                                                                                                                                                                                                                                                        reason: `${interaction.user.username}: ${reason}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                        deleteMessageSeconds: deleteDays * 24 * 60 * 60 
                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                await ModerationCase.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                guildId: guild.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                userId: target.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                moderatorId: interaction.user.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                type: 'BAN',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                reason: reason
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Renovated Embed - Same style as userinfo/serverinfo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const banEmbed = new EmbedBuilder()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .setColor(0xef4444)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .setAuthor({ 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name: 'MATURE MODERATION SYSTEM', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            iconURL: interaction.client.user?.displayAvatarURL() 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setTitle(`${EMOJIS.GENERAL.BOT} Member Banned`)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setThumbnail(target.displayAvatarURL({ size: 256 }))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .addFields(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name: `${EMOJIS.DOTS.BLACK} Target User`, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value: `**${target.username}**\n\`${target.id}\``, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inline: true 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name: `${EMOJIS.DOTS.BLACK} Moderator`, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value: `**${interaction.user.username}**\n\`${interaction.user.id}\``, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inline: true 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name: `${EMOJIS.DOTS.BLACK} Reason`, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value: reason, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inline: false 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name: `${EMOJIS.DOTS.BLACK} Message History`, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                value: deleteDays > 0 ? `Deleted last **${deleteDays}** days` : 'No messages deleted', 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        inline: true 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .setFooter({ 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                text: `Requested by ${interaction.user.username}`, 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    iconURL: interaction.user.displayAvatarURL() 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .setTimestamp();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await interaction.editReply({ embeds: [banEmbed] });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (error: any) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    console.error(error);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await interaction.editReply({ 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                embeds: [new EmbedBuilder().setColor(0xef4444).setDescription(`${EMOJIS.MOD.CROSS} **Internal Error:** ${error.message || 'An unexpected error occurred.'}`)] 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };